using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationFixture
{
    private static DistributedApplicationTestingBuilder? _appBuilder;
    private static DistributedApplication? _app;
    private static ReportingConfiguration? _reportingConfiguration;

    public static IChatClient ChatClient { get; private set; } = null!;
    public static ReportingConfiguration ReportingConfiguration =>
        _reportingConfiguration ?? throw new InvalidOperationException("Fixture not initialized.");

    [AssemblyInitialize]
    public static async Task Initialize(TestContext context)
    {
        _appBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appBuilder.BuildAsync();
        await _app.StartAsync();

        ChatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storagePath = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationFixture).Assembly.Location)!,
            "eval-results");

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: storagePath,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class ChatEvaluationTests
{
    [TestMethod]
    public async Task GreetingResponse_MeetsQualityBar()
    {
        await using var scenario = await EvaluationFixture.ReportingConfiguration
            .CreateScenarioRunAsync(scenarioName: nameof(GreetingResponse_MeetsQualityBar));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await EvaluationFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsBelowDiagnosticThreshold();
    }

    [TestMethod]
    public async Task FactualQuestion_ReturnsRelevantAnswer()
    {
        await using var scenario = await EvaluationFixture.ReportingConfiguration
            .CreateScenarioRunAsync(scenarioName: nameof(FactualQuestion_ReturnsRelevantAnswer));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await EvaluationFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsBelowDiagnosticThreshold();
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        await using var scenario = await EvaluationFixture.ReportingConfiguration
            .CreateScenarioRunAsync(scenarioName: nameof(MultiTurnConversation_MaintainsCoherence));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan."),
        };

        var response1 = await EvaluationFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What should I pack for the weather in April?"));

        var response2 = await EvaluationFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsBelowDiagnosticThreshold();
    }
}

