using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.Configuration;
using OpenAI;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationFixture
{
    private static IChatClient? _chatClient;
    private static IChatClient? _evaluatorChatClient;
    private static ReportingConfiguration? _reportingConfiguration;

    public static IChatClient ChatClient =>
        _chatClient ?? throw new InvalidOperationException("Fixture not initialized.");

    public static ReportingConfiguration ReportingConfiguration =>
        _reportingConfiguration ?? throw new InvalidOperationException("Fixture not initialized.");

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var config = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json", optional: true)
            .AddEnvironmentVariables()
            .Build();

        var deploymentName = config["AI:DeploymentName"] ?? "chat";
        var apiKey = config["AI:ApiKey"] ?? "test-key";

        _chatClient = new OpenAIClient(apiKey)
            .GetChatClient(deploymentName)
            .AsIChatClient();

        var evalDeployment = config["AI:Evaluator:DeploymentName"] ?? deploymentName;
        _evaluatorChatClient = new OpenAIClient(
                config["AI:Evaluator:ApiKey"] ?? apiKey)
            .GetChatClient(evalDeployment)
            .AsIChatClient();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static void Cleanup()
    {
        (_chatClient as IDisposable)?.Dispose();
        (_evaluatorChatClient as IDisposable)?.Dispose();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storagePath = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationFixture).Assembly.Location)!,
            "eval-results");

        var chatConfig = new ChatConfiguration(_evaluatorChatClient!);

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: storagePath,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: chatConfig);
    }
}

