using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class ChatEvaluationTests
{
    [TestMethod]
    public async Task GreetingResponse_MeetsQualityBar()
    {
        await using var scenario = await EvaluationFixture.ReportingConfiguration
            .CreateScenarioRunAsync(scenarioName: nameof(GreetingResponse_MeetsQualityBar));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await EvaluationFixture.ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        Assert.IsFalse(
            result.ContainsDiagnostics(d => d.Severity >= EvaluationDiagnosticSeverity.Error),
            "Evaluation produced error-level diagnostics.");
    }

    [TestMethod]
    public async Task FactualQuestion_ReturnsRelevantAnswer()
    {
        await using var scenario = await EvaluationFixture.ReportingConfiguration
            .CreateScenarioRunAsync(scenarioName: nameof(FactualQuestion_ReturnsRelevantAnswer));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await EvaluationFixture.ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        Assert.IsFalse(
            result.ContainsDiagnostics(d => d.Severity >= EvaluationDiagnosticSeverity.Error),
            "Evaluation produced error-level diagnostics.");
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        await using var scenario = await EvaluationFixture.ReportingConfiguration
            .CreateScenarioRunAsync(scenarioName: nameof(MultiTurnConversation_MaintainsCoherence));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan."),
        };

        var response1 = await EvaluationFixture.ChatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "What should I pack for the weather in April?"));

        var response2 = await EvaluationFixture.ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response2);

        Assert.IsFalse(
            result.ContainsDiagnostics(d => d.Severity >= EvaluationDiagnosticSeverity.Error),
            "Evaluation produced error-level diagnostics.");
    }
}

